//! Unicode character properties needed by the lexer and the regex engine, and case mapping
//! (see [`case`]).
//!
//! The tables are generated by `scripts/gen-unicode.py` from the UCD; see that script
//! for the Unicode version. ASCII is handled inline here so that the tables only cover
//! code points `>= 0x80`.

#[rustfmt::skip]
mod tables;
#[rustfmt::skip]
mod case_tables;
#[cfg(feature = "regexp-unicode-props")]
#[rustfmt::skip]
mod props;
#[cfg(feature = "regexp-unicode-props")]
pub mod property;
#[cfg(feature = "unicode-normalization")]
#[rustfmt::skip]
mod norm_tables;
#[cfg(feature = "unicode-normalization")]
pub mod normalize;

pub mod case;

pub use tables::UNICODE_VERSION;

/// Looks up `c` in a packed, sorted range table (see `tables.rs`).
fn in_table(table: &[u32], c: u32) -> bool {
    // Index of the first range that starts after `c`; the candidate is the one before.
    let idx = table.partition_point(|&e| (e >> tables::LEN_BITS) <= c);
    if idx == 0 {
        return false;
    }
    let e = table[idx - 1];
    let start = e >> tables::LEN_BITS;
    let last = start + (e & ((1 << tables::LEN_BITS) - 1));
    c <= last
}

/// Unicode `ID_Start`. Does not include `$` and `_` (see [`is_js_id_start`]).
pub fn is_id_start(c: u32) -> bool {
    if c < 0x80 {
        return (c as u8).is_ascii_alphabetic();
    }
    in_table(&tables::ID_START, c)
}

/// Unicode `ID_Continue`. Does not include `$`, ZWNJ and ZWJ (see [`is_js_id_continue`]).
pub fn is_id_continue(c: u32) -> bool {
    if c < 0x80 {
        return (c as u8).is_ascii_alphanumeric() || c == u32::from(b'_');
    }
    in_table(&tables::ID_START, c) || in_table(&tables::ID_CONTINUE_ONLY, c)
}

/// ECMAScript `IdentifierStartChar`: `ID_Start`, `$` or `_`.
pub fn is_js_id_start(c: u32) -> bool {
    c == u32::from(b'$') || c == u32::from(b'_') || is_id_start(c)
}

/// ECMAScript `IdentifierPartChar`: `ID_Continue`, `$`, ZWNJ or ZWJ.
pub fn is_js_id_continue(c: u32) -> bool {
    c == u32::from(b'$') || c == 0x200C || c == 0x200D || is_id_continue(c)
}

/// Unicode general category `Space_Separator` (Zs).
pub fn is_space_separator(c: u32) -> bool {
    if c < 0x80 {
        return c == 0x20;
    }
    in_table(&tables::SPACE_SEPARATOR, c)
}

/// ECMAScript `WhiteSpace`: TAB, VT, FF, ZWNBSP (U+FEFF) and any Zs code point (which
/// covers SP and NBSP). Line terminators are not white space.
pub fn is_js_whitespace(c: u32) -> bool {
    matches!(c, 0x09 | 0x0B | 0x0C | 0xFEFF) || is_space_separator(c)
}

/// ECMAScript `LineTerminator`: LF, CR, LS (U+2028), PS (U+2029).
pub fn is_js_line_terminator(c: u32) -> bool {
    matches!(c, 0x0A | 0x0D | 0x2028 | 0x2029)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ascii() {
        for c in 0u32..0x80 {
            let ch = char::from_u32(c).unwrap();
            assert_eq!(is_id_start(c), ch.is_ascii_alphabetic(), "{c:#x}");
            assert_eq!(
                is_id_continue(c),
                ch.is_ascii_alphanumeric() || ch == '_',
                "{c:#x}"
            );
            assert_eq!(
                is_js_id_start(c),
                ch.is_ascii_alphabetic() || ch == '_' || ch == '$'
            );
        }
        assert!(is_js_whitespace(0x20));
        assert!(is_js_whitespace(0x09));
        assert!(!is_js_whitespace(0x0A));
    }

    #[test]
    fn non_ascii_samples() {
        // Latin, Greek, CJK, astral letters.
        for c in [
            0xE9, 0x3B1, 0x4E00, 0x9FFF, 0x1D4D0, 0x20000, 0x2118, 0x212E,
        ] {
            assert!(is_id_start(c), "{c:#x}");
            assert!(is_id_continue(c), "{c:#x}");
        }
        // Combining marks, digits and connector punctuation: continue only.
        for c in [0x300, 0x660, 0x203F, 0x30FB, 0xFF65, 0xB7, 0x387] {
            assert!(!is_id_start(c), "{c:#x}");
            assert!(is_id_continue(c), "{c:#x}");
        }
        // Not identifier characters at all.
        for c in [
            0xA0, 0xB2, 0x2028, 0x2E2F, 0xFEFF, 0x1F600, 0xD800, 0x10FFFF, 0x110000,
        ] {
            assert!(!is_id_start(c), "{c:#x}");
            assert!(!is_id_continue(c), "{c:#x}");
        }
        assert!(is_js_id_continue(0x200C) && is_js_id_continue(0x200D));
        assert!(!is_js_id_start(0x200C));
    }

    #[test]
    fn whitespace() {
        let zs = [
            0x20, 0xA0, 0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007,
            0x2008, 0x2009, 0x200A, 0x202F, 0x205F, 0x3000,
        ];
        for c in 0..0x11000 {
            assert_eq!(is_space_separator(c), zs.contains(&c), "{c:#x}");
        }
        // U+180E stopped being Zs in Unicode 6.3; test262 checks this.
        assert!(!is_js_whitespace(0x180E));
        assert!(is_js_whitespace(0xFEFF));
        assert!(!is_js_whitespace(0x2028));
        assert!(is_js_line_terminator(0x2029));
    }

    #[test]
    fn table_is_sorted_and_disjoint() {
        for table in [&tables::ID_START[..], &tables::ID_CONTINUE_ONLY[..]] {
            let mut prev_end = 0x7F;
            for &e in table {
                let start = e >> tables::LEN_BITS;
                let last = start + (e & ((1 << tables::LEN_BITS) - 1));
                assert!(start > prev_end);
                prev_end = last;
            }
            assert!(prev_end <= 0x10FFFF);
        }
    }
}
